/**
 * API/countries/rules/engine.ts
 * ──────────────────────────────────────────────────────────────────────────
 * The country rules layer: types for the obligation rules and situation
 * questions imported from docs/research/<country>.md, plus the pure
 * functions that match answers to rules and compute the next date.
 *
 * No country logic lives here. Each country is data in rules/<code>.ts,
 * generated by scripts/importCountryResearch.py from the research JSON.
 * Every rule keeps its sources, its research confidence and
 * `reviewedByCounsel: false` until a partner lawyer in that country signs it
 * off (docs/LAUNCH_CHECKLIST.md).
 */

export type Confidence = "high" | "medium" | "low";

/** Legal areas, shared by all countries (check results group by these). */
export type RuleArea =
  | "immigration"
  | "property"
  | "corporate"
  | "tax"
  | "vehicle"
  | "employment"
  | "estate"
  | "identity"
  | "cross_border";

export const RULE_AREAS: RuleArea[] = [
  "immigration", "property", "corporate", "tax", "vehicle", "employment", "estate", "identity", "cross_border",
];

/** [month 1-12, day 1-31] */
export type MonthDay = [number, number];

export type DueRule =
  /** Same calendar day every year. */
  | { kind: "annual"; on: MonthDay; windowStart?: MonthDay; firstYear?: number }
  /** One date, or a list of one-off dates (the next one that has not passed). */
  | { kind: "once"; dates: string[] }
  /** Several calendar days each year (installments, quarterly payments). */
  | { kind: "installments"; dates: MonthDay[] }
  /** Yearly windows; the date is each window's last day, the window start is kept. */
  | { kind: "windows"; windows: Array<{ start: MonthDay; end: MonthDay }> }
  /** Every month on `day` of the month; null = last day of the month. */
  | { kind: "monthly"; day: number | null }
  /** Every month between business day `from` and `to` (weekends skipped); the date is day `to`. */
  | { kind: "monthlyBusinessDays"; from: number; to: number }
  /** From a date the member gives (`anchor` is the answer key). */
  | {
    kind: "relative";
    anchor: string;
    days?: number;
    months?: number;
    years?: number;
    businessDays?: number;
    /** Window: the date is anchor + days (or months/years); the window opens at anchor + windowStartDays. */
    windowStartDays?: number;
    /** Repeats every year on the anchor's anniversary. */
    annual?: boolean;
    /** Last day of the month that many months after the anchor (e.g. 1 = end of the following month). */
    endOfMonthAfter?: number;
    /** When the anchor is unknown, fall back to this yearly date (e.g. a calendar year-end). */
    fallback?: MonthDay;
  }
  /** A yearly date picked by an answer, e.g. the half of the year a company was registered. */
  | { kind: "annualByAnswer"; answer: string; map: Record<string, MonthDay> }
  /** The last day of a month picked by an answer (plate digit → month), every year, shifted by offsetDays. */
  | { kind: "monthByAnswer"; answer: string; map?: Record<string, number>; offsetDays?: number }
  /** A date range that depends on the last digits of a tax ID, summarized to the range (one per installment). */
  | { kind: "byIdDigits"; idName: string; ranges: Array<{ start: MonthDay; end: MonthDay }> }
  /** Same date as another rule of the same country. */
  | { kind: "sameAs"; ruleId: string }
  /** Happens on an event (a sale, a hire, a move); no calendar date. */
  | { kind: "event"; trigger: string }
  /** Ongoing duty or watch item; no single date. */
  | { kind: "ongoing" };

/** Every key must match one listed value; `anyOf` needs one whole group to match; `unless` excludes. */
export interface Condition {
  all: Record<string, string[]>;
  anyOf?: Array<Record<string, string[]>>;
  unless?: Record<string, string[]>;
}

export interface CountryRule {
  id: string; // research id, e.g. "CO_IMM_RESIDENT_TRASPASO_2026"
  country: string; // CountryCode
  area: RuleArea;
  title: string; // ends with "may require review"
  meaning: string; // "what this usually means", plain language
  when: Condition;
  due: DueRule;
  /** Weekend dates move: "next" business day, or the "previous" one (e.g. "last business day"). */
  rollWeekend?: "next" | "previous";
  /** The due rule in words, from the research (shown when there is no date). */
  dueText: string;
  /** True when the dates come from one year's calendar (e.g. 2026) and later years may differ. */
  estimatedFromYear?: number;
  authority: string;
  consequence: string;
  sources: string[];
  confidence: Confidence;
  notes: string;
  reviewedByCounsel: boolean;
  /** Optional link to a LEGAL_PRIORITIES entry the member can track. */
  priorityId?: string;
}

export interface QuestionOption {
  value: string;
  label: string;
  /** Facts this answer sets for rule matching (a list = several values hold). */
  sets?: Record<string, string | string[]>;
}

export interface CountryQuestion {
  key: string; // answer key
  /** "check": asked in the free check and the join form; "profile": asked later in the member profile. */
  stage: "check" | "profile";
  question: string;
  why?: string;
  help?: string;
  type: "choice" | "multi" | "date" | "month";
  options: QuestionOption[];
  /** Shown only when every listed answer matches (raw answers, before `sets`). */
  showIf?: Record<string, string[]>;
  optional?: boolean;
  /** For a date question that means different dates: the fact key to store it under, by another answer. */
  dateAs?: { by: string; map: Record<string, string> };
  /** "research": from docs/research; "ilp": added so every rule condition has a question. */
  source: "research" | "ilp";
}

export interface CountryRuleset {
  country: string;
  researchDate: string;
  questions: CountryQuestion[];
  rules: CountryRule[];
}

// ─── Answers → facts ───────────────────────────────────────────────────────

export type Answers = Record<string, string | string[]>;
export type Facts = Record<string, string[]>;

const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

/** Is the question shown for these raw answers? */
export function questionShown(q: CountryQuestion, answers: Answers): boolean {
  if (!q.showIf) return true;
  return Object.entries(q.showIf).every(([k, allowed]) => {
    const v = answers[k];
    const vals = Array.isArray(v) ? v : v === undefined ? [] : [v];
    return vals.some((x) => allowed.includes(x));
  });
}

/**
 * Keep only answers to questions that exist, are shown, and hold a listed
 * value (or a valid date / month). Unknown keys are dropped.
 */
export function cleanAnswers(questions: CountryQuestion[], raw: Record<string, unknown>): Answers {
  const out: Answers = {};
  // Two passes so a follow-up whose showIf depends on a later key still resolves.
  for (let pass = 0; pass < 2; pass++) {
    for (const q of questions) {
      const v = raw[q.key];
      if (v === undefined || v === null || v === "") continue;
      if (q.type === "date") {
        if (typeof v === "string" && DATE_RE.test(v) && !Number.isNaN(Date.parse(`${v}T12:00:00Z`))) out[q.key] = v;
      } else if (q.type === "multi") {
        const list = (Array.isArray(v) ? v : [v]).map(String).filter((x) => q.options.some((o) => o.value === x));
        if (list.length) out[q.key] = [...new Set(list)];
      } else {
        const s = String(v);
        if (q.options.some((o) => o.value === s)) out[q.key] = s;
      }
    }
    for (const q of questions) if (out[q.key] !== undefined && !questionShown(q, out)) delete out[q.key];
  }
  return out;
}

/**
 * Facts for rule matching: each raw answer, then whatever its option `sets`
 * (which may replace the raw value, e.g. "active" company → hasCompany "yes").
 * Date questions with `dateAs` are stored under the mapped key as well.
 */
export function answersToFacts(questions: CountryQuestion[], answers: Answers): Facts {
  const facts: Facts = {};
  const add = (k: string, v: string | string[], replace = false) => {
    const vals = Array.isArray(v) ? v : [v];
    facts[k] = replace ? [...vals] : [...new Set([...(facts[k] ?? []), ...vals])];
  };
  for (const q of questions) {
    const v = answers[q.key];
    if (v === undefined) continue;
    add(q.key, v);
    if (q.type === "date" && q.dateAs) {
      const by = answers[q.dateAs.by];
      const target = typeof by === "string" ? q.dateAs.map[by] : undefined;
      if (target) add(target, v as string, true);
    }
  }
  // `sets` run after every raw answer, so they win over a raw value with the same key.
  const setKeys = new Set<string>();
  for (const q of questions) {
    const v = answers[q.key];
    if (v === undefined) continue;
    for (const val of Array.isArray(v) ? v : [v]) {
      const opt = q.options.find((o) => o.value === val);
      for (const [k, sv] of Object.entries(opt?.sets ?? {})) {
        add(k, sv, !setKeys.has(k));
        setKeys.add(k);
      }
    }
  }
  return facts;
}

function groupMatches(group: Record<string, string[]>, facts: Facts): boolean {
  return Object.entries(group).every(([k, allowed]) => (facts[k] ?? []).some((v) => allowed.includes(v)));
}

export function ruleApplies(rule: CountryRule, facts: Facts): boolean {
  const w = rule.when;
  if (!groupMatches(w.all, facts)) return false;
  if (w.anyOf?.length && !w.anyOf.some((g) => groupMatches(g, facts))) return false;
  if (w.unless && Object.keys(w.unless).length && groupMatches(w.unless, facts)) return false;
  return true;
}

// ─── Dates ─────────────────────────────────────────────────────────────────

const DAY_MS = 86_400_000;
const noon = (y: number, m: number, d: number) => new Date(Date.UTC(y, m - 1, d, 12));
const startOfDay = (now: Date) => new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
const lastDay = (y: number, m: number) => new Date(Date.UTC(y, m, 0, 12)); // day 0 of next month

/** Move a Saturday or Sunday to Monday ("next") or Friday ("previous"). */
export function rollWeekend(d: Date, dir: "next" | "previous" = "next"): Date {
  const out = new Date(d);
  while (out.getUTCDay() === 0 || out.getUTCDay() === 6) out.setUTCDate(out.getUTCDate() + (dir === "next" ? 1 : -1));
  return out;
}

function addMonths(d: Date, n: number): Date {
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth() + n;
  const day = d.getUTCDate();
  const last = new Date(Date.UTC(y, m + 1, 0)).getUTCDate();
  return new Date(Date.UTC(y, m, Math.min(day, last), 12));
}

function addBusinessDays(d: Date, n: number): Date {
  const out = new Date(d);
  let left = n;
  while (left > 0) {
    out.setUTCDate(out.getUTCDate() + 1);
    if (out.getUTCDay() !== 0 && out.getUTCDay() !== 6) left--;
  }
  return out;
}

/** The `n`-th business day (Mon-Fri) of a month. */
function nthBusinessDay(y: number, m: number, n: number): Date {
  let d = noon(y, m, 1);
  let count = d.getUTCDay() === 0 || d.getUTCDay() === 6 ? 0 : 1;
  while (count < n) {
    d = new Date(d.getTime() + DAY_MS);
    if (d.getUTCDay() !== 0 && d.getUTCDay() !== 6) count++;
  }
  return d;
}

export interface DueResult {
  dueAt: Date;
  windowStartAt?: Date;
}

/** The first yearly occurrence of a month-day on or after `today` (rolled), from `fromYear`. */
function nextYearly(md: MonthDay, today: Date, roll?: "next" | "previous", fromYear?: number): Date {
  const y0 = Math.max(today.getUTCFullYear(), fromYear ?? 0);
  for (let y = y0; y <= y0 + 1; y++) {
    const raw = noon(y, md[0], md[1]);
    const d = roll ? rollWeekend(raw, roll) : raw;
    if (d >= today) return d;
  }
  const d = noon(y0 + 2, md[0], md[1]);
  return roll ? rollWeekend(d, roll) : d;
}

function anchorDate(facts: Facts, key: string): Date | null {
  const v = facts[key]?.[0];
  if (!v || !DATE_RE.test(v)) return null;
  const d = new Date(`${v}T12:00:00.000Z`);
  return Number.isNaN(d.getTime()) ? null : d;
}

/**
 * Next date for a rule, or null when it has no calendar date (ongoing,
 * event) or needs an answer the member has not given.
 */
export function nextDue(
  rule: Pick<CountryRule, "due" | "rollWeekend">,
  facts: Facts,
  now: Date,
  lookup?: (ruleId: string) => Pick<CountryRule, "due" | "rollWeekend"> | undefined,
): DueResult | null {
  const today = startOfDay(now);
  const y = today.getUTCFullYear();
  const roll = rule.rollWeekend;
  const r = (d: Date) => (roll ? rollWeekend(d, roll) : d);
  const due = rule.due;
  switch (due.kind) {
    case "annual": {
      const d = nextYearly(due.on, today, roll, due.firstYear);
      if (!due.windowStart) return { dueAt: d };
      const ws = noon(d.getUTCFullYear(), due.windowStart[0], due.windowStart[1]);
      return { dueAt: d, windowStartAt: ws <= d ? ws : noon(d.getUTCFullYear() - 1, due.windowStart[0], due.windowStart[1]) };
    }
    case "once": {
      const next = due.dates.map((s) => r(new Date(`${s}T12:00:00.000Z`))).filter((d) => d >= today).sort((a, b) => a.getTime() - b.getTime());
      return next[0] ? { dueAt: next[0] } : null;
    }
    case "installments": {
      const next = [y, y + 1]
        .flatMap((yr) => due.dates.map(([m, d]) => r(noon(yr, m, d))))
        .filter((d) => d >= today)
        .sort((a, b) => a.getTime() - b.getTime());
      return next[0] ? { dueAt: next[0] } : null;
    }
    case "windows":
    case "byIdDigits": {
      const list = (due.kind === "windows" ? due.windows : due.ranges)
        .flatMap((w) => [y - 1, y, y + 1].map((yr) => {
          const end = r(noon(yr, w.end[0], w.end[1]));
          // A window that wraps the year (e.g. Dec to Jan) opens the year before.
          const startYear = w.start[0] > w.end[0] ? yr - 1 : yr;
          return { start: noon(startYear, w.start[0], w.start[1]), end };
        }))
        .filter((w) => w.end >= today)
        .sort((a, b) => a.end.getTime() - b.end.getTime());
      return list[0] ? { dueAt: list[0].end, windowStartAt: list[0].start } : null;
    }
    case "monthly": {
      for (let i = 0; i < 3; i++) {
        const m = today.getUTCMonth() + 1 + i;
        const yr = y + Math.floor((m - 1) / 12);
        const mm = ((m - 1) % 12) + 1;
        const raw = due.day === null ? lastDay(yr, mm) : noon(yr, mm, Math.min(due.day, lastDay(yr, mm).getUTCDate()));
        const d = r(raw);
        if (d >= today) return { dueAt: d };
      }
      return null;
    }
    case "monthlyBusinessDays": {
      for (let i = 0; i < 3; i++) {
        const m = today.getUTCMonth() + 1 + i;
        const yr = y + Math.floor((m - 1) / 12);
        const mm = ((m - 1) % 12) + 1;
        const end = nthBusinessDay(yr, mm, due.to);
        if (end >= today) return { dueAt: end, windowStartAt: nthBusinessDay(yr, mm, due.from) };
      }
      return null;
    }
    case "relative": {
      const a = anchorDate(facts, due.anchor);
      if (!a) return due.fallback ? { dueAt: nextYearly(due.fallback, today, roll) } : null;
      const shift = (base: Date) => {
        let d = new Date(base);
        if (due.years) d = addMonths(d, 12 * due.years);
        if (due.months) d = addMonths(d, due.months);
        if (due.days) d = new Date(d.getTime() + due.days * DAY_MS);
        if (due.businessDays) d = addBusinessDays(d, due.businessDays);
        if (due.endOfMonthAfter !== undefined) d = lastDay(d.getUTCFullYear(), d.getUTCMonth() + 1 + due.endOfMonthAfter);
        return r(d);
      };
      let d = shift(a);
      if (due.annual) {
        // Next anniversary on or after today.
        let k = 0;
        while (d < today && k < 200) {
          k++;
          d = shift(addMonths(a, 12 * k));
        }
      }
      const out: DueResult = { dueAt: d };
      if (due.windowStartDays !== undefined) {
        out.windowStartAt = new Date(a.getTime() + due.windowStartDays * DAY_MS);
        if (due.annual) out.windowStartAt = new Date(d.getTime() + (due.windowStartDays - (due.days ?? 0)) * DAY_MS);
      }
      return out;
    }
    case "annualByAnswer": {
      const v = facts[due.answer]?.[0];
      const md = v ? due.map[v] : undefined;
      return md ? { dueAt: nextYearly(md, today, roll) } : null;
    }
    case "monthByAnswer": {
      const v = facts[due.answer]?.[0];
      const month = v === undefined ? undefined : due.map ? due.map[v] : Number(v);
      if (!month || month < 1 || month > 12) return null;
      for (const yr of [y, y + 1]) {
        const d = new Date(lastDay(yr, month).getTime() + (due.offsetDays ?? 0) * DAY_MS);
        if (r(d) >= today) return { dueAt: r(d) };
      }
      return null;
    }
    case "sameAs": {
      const other = lookup?.(due.ruleId);
      if (!other || other.due.kind === "sameAs") return null;
      return nextDue(other, facts, now);
    }
    case "event":
    case "ongoing":
      return null;
  }
}
